import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    comment: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [comment, setComment] = useState('');

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));

  const handleSubmit = () => {
    onSubmit({ fullName, email, phone, address, comment });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        maxWidth: 480,
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Имя и фамилия"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxTextareaField
            label="Адрес доставки"
            required
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxTextareaField
            label="Комментарий к адресу"
            rows={2}
            helperText="Например, код домофона или этаж"
            value={comment}
            onChange={(event) => setComment(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <div>
            <div style={{ color: 'var(--jx-text-2)' }}>Имя и фамилия</div>
            <div>{fullName || '—'}</div>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-2)' }}>Электронная почта</div>
            <div>{email || '—'}</div>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-2)' }}>Телефон</div>
            <div>{phone ? `+7${phone}` : '—'}</div>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-2)' }}>Адрес</div>
            <div>{address || '—'}</div>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-2)' }}>Комментарий</div>
            <div>{comment || '—'}</div>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

